{"tool": "write", "path": "reports/export.py", "content": """"Reports CSV exporter."""

from collections.abc import Mapping


def _encode(value):
    """Convert a field value to its CSV cell (RFC 4180 minimal quoting)."""
    if value is None:
        s = ""
    else:
        s = str(value)
    if any(ch in s for ch in ('"', ",", "\r", "\n")):
        return '"' + s.replace('"', '""') + '"'
    return s


def _get_field(row, col):
    """Fetch a column from a row mapping, tolerating duck-typed mappings."""
    if isinstance(row, Mapping):
        return row.get(col, None)
    getter = getattr(row, "get", None)
    if callable(getter):
        return getter(col, None)
    try:
        return row[col]
    except (KeyError, IndexError, TypeError):
        return None


def export_csv(rows, columns):
    """Export mappings in column order as RFC 4180 CSV, including the header.

    rows is an iterable of mappings; columns is an ordered iterable of unique
    string column names. Returns a str with a CSV header then one record per
    row, in that order. Comma delimiters, CRLF record endings, RFC 4180 minimal
    quoting and quote doubling. Missing fields and None become empty strings;
    other values become str(value). Unselected fields are ignored.

    Raises ValueError for duplicate or non-string column names.
    """
    cols = list(columns)  # one-shot safe; do not mutate caller's columns
    seen = set()
    for col in cols:
        if not isinstance(col, str):
            raise ValueError("column names must be strings")
        if col in seen:
            raise ValueError("duplicate column name: %r" % (col,))
        seen.add(col)

    header = ",".join(_encode(col) for col in cols)
    records = [header]
    for row in rows:
        records.append(",".join(_encode(_get_field(row, col)) for col in cols))
    return "\r\n".join(records) + "\r\n"
